84	// template's exact fields when it lands at submission position seq (JSON seq
85	// encoding differs at seq 0, which is omitted), using an all-ASCII probe
86	// payload (one JSON byte per character).
87	func submitOverhead(t *testing.T, template Envelope, seq int64, probeLen int) int64 {
