150		// (source, destination, nonce) triplet, both covered and unexpired.
151		fillerTmpl := Envelope{Message: Message{ID: "filler", From: "a", To: "b", Nonce: 99, ProofAt: 10}}
152		keep1 := Envelope{
153			Message:   Message{ID: "keep1", From: "a", To: "b", Nonce: 10, Payload: "body-keep1", ProofAt: 20},
154			ExpiresAt: 9_000_000_000_000,
155		}
156		keep2 := Envelope{
157			Message:   Message{ID: "keep2", From: "a", To: "c", Nonce: 11, Payload: "body-keep2", ProofAt: 30},
158			ExpiresAt: 9_000_000_000_001,
159		}
160		win := Envelope{
161			Message:   Message{ID: "win", From: "a", To: "shared-dest", Nonce: 77, Payload: "body-win", ProofAt: 50},
162			ExpiresAt: 9_000_000_000_000,
163		}
164		lose := Envelope{
165			Message:   Message{ID: "lose", From: "a", To: "shared-dest", Nonce: 77, Payload: "body-lose", ProofAt: 60},
166			ExpiresAt: 9_000_000_000_000,
167		}
168	
169		// Measure the real framed sizes. The filler's payload length is chosen
170		// below so that the post-compaction snapshot equals threshold-margin:
171		// snapshot = base + one checkpoint + filler frame + the four small frames.
172		gaugeBase, cp, smallFrames := gaugeFrames(t, []Envelope{keep1, keep2, win, lose})
173		var smallTotal int64
174		for _, f := range smallFrames {
175			smallTotal += f
176		}
177		fillerOverhead := submitOverhead(t, fillerTmpl, 0, 4096)
178		fillerPayloadLen := compactThreshold - margin - gaugeBase - cp - smallTotal - fillerOverhead
179		if fillerPayloadLen <= 0 {
180			t.Fatalf("setup arithmetic leaves no filler payload: %d", fillerPayloadLen)
181		}
182		filler := fillerTmpl
183		filler.Message.Payload = strings.Repeat("Z", int(fillerPayloadLen))
184		fillerFrame := fillerOverhead + fillerPayloadLen
185	
186		// Number of equal-time checkpoints with which to pad the empty log so
187		// that lose's frame is exactly the one that crosses:
188		//
189		//	base + n*cp + fillerFrame + smallTotal > threshold   (lose crosses)
190		//	base + n*cp + fillerFrame + smallTotal <= threshold + loseFrame
191		//	                                                     (nothing crosses early)
192		//
193		// i.e. margin+cp < n*cp <= margin+cp+loseFrame. The smallest strict n
194		// lands inside the window (which is one loseFrame wide). The runtime
195		// boundary checks after the submits verify both sides with real sizes.
196		nCheckpoints := int((margin+cp)/cp) + 1
197		if int64(nCheckpoints)*cp <= margin+cp {
198			t.Fatalf("padding arithmetic: %d checkpoints * %d must exceed %d", nCheckpoints, cp, margin+cp)
199		}
200	
201		dir := t.TempDir()
202		q, err := Open(dir)
203		if err != nil {
204			t.Fatalf("Open: %v", err)
205		}
206		defer q.Close()
207		if err := q.RegisterSource("a"); err != nil {
208			t.Fatal(err)
209		}
210		if err := q.UpsertHeader(Header{Chain: "a", Height: 100, Root: "0x100", Trusted: true}); err != nil {
211			t.Fatal(err)
212		}
213		base := q.store.size
214		if base != gaugeBase {
215			t.Fatalf("setup base mismatch: gauge %d real %d", gaugeBase, base)
216		}
217	
218		// Padding: no messages exist yet, so the repeated equal-time advances
219		// append checkpoint frames and nothing else.
220		for i := 0; i < nCheckpoints; i++ {
221			rep, err := q.Advance(1000)
222			if err != nil {
223				t.Fatal(err)
224			}
225			if len(rep.Results) != 0 {
226				t.Fatalf("padding advances must process nothing: %+v", rep.Results)
227			}
228		}
229		wantSize := base + int64(nCheckpoints)*cp
230		if q.store.size != wantSize {
231			t.Fatalf("padding size: want %d got %d", wantSize, q.store.size)
232		}
233	
234		// Prior messages, none of which may cross the line on its own.
235		for _, e := range []Envelope{filler, keep1, keep2, win} {
236			if _, err := q.Submit(e); err != nil {
237				t.Fatal(err)
238			}
239			if q.store.size > compactThreshold {
240				t.Fatalf("submit %s crossed the threshold early at %d", e.Message.ID, q.store.size)
241			}
242		}
243		preLose := q.store.size
244		if preLose+smallFrames[3] <= compactThreshold {
245			t.Fatalf("setup arithmetic: lose would not cross: pre=%d frame=%d", preLose, smallFrames[3])
246		}
247	
248		// THE crossing submit: ordinary Submit success must include lose in the
249		// automatically compacted log.
250		rec, err := q.Submit(lose)
251		if err != nil {
252			t.Fatalf("the threshold-crossing submit must succeed: %v", err)
253		}
254		predictedPost := base + cp + fillerFrame + smallTotal
255		if q.store.size != predictedPost {
256			t.Fatalf("automatic compaction must leave exactly the snapshot size: got %d want %d",
257				q.store.size, predictedPost)
258		}
259		if q.store.size >= compactThreshold {
260			t.Fatalf("snapshot must shrink below the threshold: %d >= %d", q.store.size, compactThreshold)
261		}
262		if info, err := os.Stat(filepath.Join(dir, logName)); err != nil || info.Size() != q.store.size {
263			t.Fatalf("on-disk log size %v disagrees with compacted size %d: %v", info, q.store.size, err)
264		}
265		// The trigger echo is its untouched pending record: compaction never
266		// processed it or advanced its seq.
267		if rec.Status != StatusPending || rec.Reason != "awaiting first processing" ||
268			rec.Attempts != 0 || rec.NextRetry != 0 || rec.Seq != 4 {
269			t.Fatalf("triggering submit echo must be a fresh pending record: %+v", rec)
270		}
271	
272		// All five records are queryable with original content and pending state;
273		// the trigger is appended at the end, each id exactly once.
274		wantIDs := []string{"filler", "keep1", "keep2", "win", "lose"}
275		pendingReason := "awaiting first processing"
276		for _, e := range []Envelope{filler, keep1, keep2, win, lose} {
277			assertRecordExact(t, q, e, StatusPending, pendingReason, 0, 0)
278		}
279		all := q.Queries()
280		if len(all) != 5 {
281			t.Fatalf("want 5 records, got %d: %v", len(all), listingIDs(all))
282		}
283		for i, want := range wantIDs {
284			if all[i].ID != want {
285				t.Fatalf("listing must be in first-submission order: want %v got %v", wantIDs, listingIDs(all))
286			}
287		}
288		counts := map[string]int{}
289		for _, r := range all {
290			counts[r.ID]++
291		}
292		for id, n := range counts {
293			if n != 1 {
294				t.Fatalf("record %s appears %d times", id, n)
295			}
296		}
297	
298		// Submission boundary while records are still pending: identical
299		// resubmit returns the existing record, different content conflicts,
300		// with no new entry, no seq consumed and no reordering.
301		echo, err := q.Submit(keep1)
302		if err != nil {
303			t.Fatalf("identical resubmit after compaction must return the record: %v", err)
304		}
305		if echo.Seq != 1 || echo.Status != StatusPending || echo.Attempts != 0 || echo.NextRetry != 0 {
306			t.Fatalf("identical resubmit must echo the existing pending record: %+v", echo)
307		}
308		if len(q.records) != 5 || q.order.len() != 5 || q.nextSeq != 5 {
309			t.Fatalf("identical resubmit added an entry: records=%d order=%v nextSeq=%d",
310				len(q.records), q.order.ids(), q.nextSeq)
311		}
312		bad := keep1
313		bad.Message.Payload = "body-keep1-CHANGED"
314		if _, err := q.Submit(bad); !errors.Is(err, ErrConflict) {
315			t.Fatalf("same id with different content after compaction must be ErrConflict, got %v", err)
316		}
317		assertRecordExact(t, q, keep1, StatusPending, pendingReason, 0, 0)
318		if len(q.records) != 5 || q.nextSeq != 5 {
319			t.Fatalf("rejected submit must add no record and consume no seq: records=%d nextSeq=%d",
320				len(q.records), q.nextSeq)
321		}
322		for i, want := range wantIDs {
323			if q.order.ids()[i] != want {
324				t.Fatalf("processing order changed after the rejected submit: want %v got %v", wantIDs, q.order.ids())
325			}
326		}
327	
328		// Close and reopen the same state directory: the triggering submit must
329		// not exist only before closing.
330		if err := q.Close(); err != nil {
331			t.Fatal(err)
332		}
333		q2, err := Open(dir)
334		if err != nil {
335			t.Fatalf("reopen the compacted directory: %v", err)
336		}
337		defer q2.Close()
338		if q2.Now() != 1000 {
339			t.Fatalf("processing time lost across compaction/reopen: want 1000 got %d", q2.Now())
340		}
341		all = q2.Queries()
342		if len(all) != 5 {
343			t.Fatalf("after reopen want 5 records, got %d: %v", len(all), listingIDs(all))
344		}
345		for i, want := range wantIDs {
346			if all[i].ID != want {
347				t.Fatalf("order lost across reopen: want %v got %v", wantIDs, listingIDs(all))
348			}
349		}
350		for _, e := range []Envelope{filler, keep1, keep2, win, lose} {
351			assertRecordExact(t, q2, e, StatusPending, pendingReason, 0, 0)
352		}
353		// The same submission boundary holds against the compacted bytes, before
354		// anything is processed.
355		if _, err := q2.Submit(win); err != nil {
356			t.Fatalf("identical resubmit after reopen must still be idempotent: %v", err)
357		}
358		bad2 := lose
359		bad2.Message.ProofAt = 61
360		if _, err := q2.Submit(bad2); !errors.Is(err, ErrConflict) {
361			t.Fatalf("content conflict after reopen must stay ErrConflict, got %v", err)
362		}
363		assertRecordExact(t, q2, lose, StatusPending, pendingReason, 0, 0)
364		if len(q2.records) != 5 {
365			t.Fatalf("post-reopen rejected submit added a record: %d", len(q2.records))
366		}
367	
368		// Continue delivery after the compaction both messages lived through:
369		// processing follows first-submission order. The bystanders and filler
370		// deliver; win (first of the shared-nonce pair) succeeds and lose ends
371		// replay naming win; the triggering submit gets no priority.
372		rep, err := q2.Advance(2000)
373		if err != nil {
374			t.Fatalf("advance after compaction: %v", err)
375		}
376		wantResults := []Result{
377			{ID: "filler", Status: StatusSuccess, Reason: "delivered; proof verified by trusted header at height 100"},
378			{ID: "keep1", Status: StatusSuccess, Reason: "delivered; proof verified by trusted header at height 100"},
379			{ID: "keep2", Status: StatusSuccess, Reason: "delivered; proof verified by trusted header at height 100"},
380			{ID: "win", Status: StatusSuccess, Reason: "delivered; proof verified by trusted header at height 100"},
381			{ID: "lose", Status: StatusReplay, Reason: "nonce combination already consumed by message win"},
382		}
383		if len(rep.Results) != len(wantResults) {
384			t.Fatalf("want %d ordered results, got %+v", len(wantResults), rep.Results)
385		}
386		for i, w := range wantResults {
387			if rep.Results[i] != w {
388				t.Fatalf("result %d: want %+v got %+v", i, w, rep.Results[i])
389			}
390		}
391	
392		// The shared-nonce pair: one attempt each, no retry scheduled, original
393		// payloads still viewable — the trigger's body included.
394		assertRecordExact(t, q2, win, StatusSuccess,
395			"delivered; proof verified by trusted header at height 100", 1, 0)
396		assertRecordExact(t, q2, lose, StatusReplay,
397			"nonce combination already consumed by message win", 1, 0)
398		if winner := q2.consumed[newConsumeToken("a", "shared-dest", 77)]; winner != "win" {
399			t.Fatalf("nonce consumption must belong to the first-submitted win, got %q", winner)
400		}
401		// The prior messages and the large filler keep their exact content.
402		assertRecordExact(t, q2, filler, StatusSuccess,
403			"delivered; proof verified by trusted header at height 100", 1, 0)
404		assertRecordExact(t, q2, keep1, StatusSuccess,
405			"delivered; proof verified by trusted header at height 100", 1, 0)
406		assertRecordExact(t, q2, keep2, StatusSuccess,
407			"delivered; proof verified by trusted header at height 100", 1, 0)
408	
409		// Terminal ordering is stable across yet another reopen, and a later
410		// advance reprocesses nothing.
411		if err := q2.Close(); err != nil {
412			t.Fatal(err)
413		}
414		q3, err := Open(dir)
415		if err != nil {
416			t.Fatal(err)
417		}
418		defer q3.Close()
419		all = q3.Queries()
420		if len(all) != 5 {
421			t.Fatalf("final reopen: want 5 records, got %v", listingIDs(all))
422		}
423		for i, want := range wantIDs {
424			if all[i].ID != want {
425				t.Fatalf("final order changed: want %v got %v", wantIDs, listingIDs(all))
426			}
427		}
428		assertRecordExact(t, q3, lose, StatusReplay,
429			"nonce combination already consumed by message win", 1, 0)
430		if winner := q3.consumed[newConsumeToken("a", "shared-dest", 77)]; winner != "win" {
431			t.Fatalf("consumption lost after final reopen: %q", winner)
432		}
433		again, err := q3.Advance(3000)
434		if err != nil {
435			t.Fatal(err)
436		}
437		if len(again.Results) != 0 {
438			t.Fatalf("terminal records must not be reprocessed: %+v", again.Results)
439		}
440	}
441	
442	// TestAutoCompactDuringSubmissionLeavesPriorStatusesUntouched crosses the
443	// threshold with already-PROCESSED records of different kinds: a success and
444	// a waiting record mid-backoff. The submit-triggered compaction must preserve
445	// their statuses, reasons, attempt counts and retry schedules exactly, and
446	// the waiting backoff must continue on its canonical schedule afterwards.
447	func TestAutoCompactDuringSubmissionLeavesPriorStatusesUntouched(t *testing.T) {
448		dir := t.TempDir()
449		q, err := Open(dir)
450		if err != nil {
451			t.Fatal(err)
452		}
453		defer q.Close()
454		if err := q.RegisterSource("a"); err != nil {
455			t.Fatal(err)
456		}
457		// Trusted height 50: done (proof 10) delivers; waiting (proof 90) parks.
458		if err := q.UpsertHeader(Header{Chain: "a", Height: 50, Root: "0x50", Trusted: true}); err != nil {
459			t.Fatal(err)
460		}
461		if _, err := q.Submit(env("done", "a", "b", 1, 10, 0)); err != nil {
462			t.Fatal(err)
463		}
464		if _, err := q.Submit(env("waiting", "a", "b", 2, 90, 0)); err != nil {
465			t.Fatal(err)
466		}
467		if _, err := q.Advance(1000); err != nil {
468			t.Fatal(err)
469		}
470		wantDone := statusOf(t, q, "done")
471		wantWaiting := statusOf(t, q, "waiting")
472		if wantDone.Status != StatusSuccess || wantDone.Attempts != 1 || wantDone.NextRetry != 0 {
473			t.Fatalf("setup done wrong: %+v", wantDone)
474		}
475		if wantWaiting.Status != StatusWaiting || wantWaiting.Attempts != 1 || wantWaiting.NextRetry != 2000 {
476			t.Fatalf("setup waiting wrong: %+v", wantWaiting)
477		}
478	
479		// Normalize to the snapshot floor with both processed records present:
480		// one checkpoint (now=1000) is carried, so later padding checkpoints are
481		// exactly the bytes a fresh snapshot drops.
482		if err := q.store.compact(q.snapshot()); err != nil {
483			t.Fatal(err)
484		}
485		snapshotFloor := q.store.size
486		if snapshotFloor >= compactThreshold {
487			t.Fatalf("setup snapshot already at threshold: %d", snapshotFloor)
488		}
489	
490		// Filler is itself the crossing submit; its retained payload sizes the
491		// next snapshot to 4 KiB below the threshold.
492		fillerTmpl := Envelope{Message: Message{ID: "filler2", From: "a", To: "b", Nonce: 9, ProofAt: 10}}
493		overhead := submitOverhead(t, fillerTmpl, 2, 4096)
494		payloadLen := compactThreshold - 4096 - snapshotFloor - overhead
495		if payloadLen <= 0 {
496			t.Fatalf("setup arithmetic leaves no payload: %d", payloadLen)
497		}
498		frame := overhead + payloadLen
499	
500		// Pad with equal-time checkpoints: at 1000 the waiting record is not
501		// reprocessed (its last processing was that same instant) and done is
502		// terminal. Stop at the first count where appending the filler crosses.
503		for q.store.size+frame <= compactThreshold {
504			rep, err := q.Advance(1000)
505			if err != nil {
506				t.Fatal(err)
507			}
508			if len(rep.Results) != 0 {
509				t.Fatalf("padding advances must not reprocess waiting/done: %+v", rep.Results)
510			}
511		}
512		if q.store.size > compactThreshold {
513			t.Fatalf("padding crossed without the filler: %d", q.store.size)
514		}
515		before := q.store.size
516	
517		filler := fillerTmpl
518		filler.Message.Payload = strings.Repeat("Z", int(payloadLen))
519		rec, err := q.Submit(filler)
520		if err != nil {
521			t.Fatalf("the threshold-crossing submit must succeed: %v", err)
522		}
523		if q.store.size != snapshotFloor+frame {
524			t.Fatalf("compacted size: want %d got %d", snapshotFloor+frame, q.store.size)
525		}
526		if q.store.size >= compactThreshold || before+frame <= compactThreshold {
527			t.Fatalf("filler must be the genuine crossing submit: before=%d frame=%d after=%d threshold=%d",
528				before, frame, q.store.size, compactThreshold)
529		}
530		if rec.Status != StatusPending || rec.Attempts != 0 || rec.NextRetry != 0 {
531			t.Fatalf("triggering filler must stay pending: %+v", rec)
532		}
533	
534		// Prior statuses, reasons, attempts, schedules and content are unchanged.
535		if got := statusOf(t, q, "done"); got != wantDone {
536			t.Fatalf("success record changed across submit-triggered compaction:\nbefore=%+v\nafter =%+v", wantDone, got)
537		}
538		if got := statusOf(t, q, "waiting"); got != wantWaiting {
539			t.Fatalf("waiting record changed across submit-triggered compaction:\nbefore=%+v\nafter =%+v", wantWaiting, got)
540		}
541		assertRecordExact(t, q, filler, StatusPending, "awaiting first processing", 0, 0)
542	
543		// Reopen from the compacted bytes: the processed states are still exact.
544		if err := q.Close(); err != nil {
545			t.Fatal(err)
546		}
547		q2, err := Open(dir)
548		if err != nil {
549			t.Fatal(err)
550		}
551		defer q2.Close()
552		if got := statusOf(t, q2, "done"); got != wantDone {
553			t.Fatalf("success record lost across reopen:\nbefore=%+v\nafter =%+v", wantDone, got)
554		}
555		if got := statusOf(t, q2, "waiting"); got != wantWaiting {
556			t.Fatalf("waiting record lost across reopen:\nbefore=%+v\nafter =%+v", wantWaiting, got)
557		}
558		assertRecordExact(t, q2, filler, StatusPending, "awaiting first processing", 0, 0)
559	
560		// The preserved backoff continues on its canonical 1s/2s schedule.
561		if _, err := q2.Advance(2000); err != nil {
562			t.Fatal(err)
563		}
564		r := statusOf(t, q2, "waiting")
565		if r.Status != StatusWaiting || r.Attempts != 2 || r.NextRetry != 4000 {
566			t.Fatalf("waiting backoff must continue on the canonical schedule after compaction: %+v", r)
567		}
568	}
