116			}
117		}
118	
119		rep, err := q.Advance(1000)
120		if err != nil {
121			t.Fatal(err)
122		}
123		wantResults := []struct {
124			id     string
125			status string
126		}{
127			{idFF, StatusSuccess},
128			{idFE, StatusWaiting},
129			{idFD, StatusSuccess},
130			{"loser", StatusReplay},
131		}
132		if len(rep.Results) != len(wantResults) {
133			t.Fatalf("results = %+v", rep.Results)
134		}
135		for i, want := range wantResults {
136			got := rep.Results[i]
137			if !bytes.Equal([]byte(got.ID), []byte(want.id)) || got.Status != want.status {
138				t.Fatalf("result %d = (% x, %s), want (% x, %s)", i, got.ID, got.Status, want.id, want.status)
139			}
140		}
141		loserReason := "nonce combination already consumed by message " + idFF
142		if got, _ := q.Query("loser"); !bytes.Equal([]byte(got.Reason), []byte(loserReason)) {
143			t.Fatalf("replay reason changed: want % x got % x", loserReason, got.Reason)
144		}
145	
146		// fe waits: attempts and retry schedule are attached to the raw-bytes id.
147		if got, _ := q.Query(idFE); got.Status != StatusWaiting || got.Attempts != 1 || got.NextRetry != 2000 {
148			t.Fatalf("waiting state for % x: %+v", idFE, got)
149		}
150	
151		// Same-id rules survive the raw-bytes keys.
152		if _, err := q.Submit(envFE); err != nil { // identical, still waiting
153			t.Fatalf("identical resubmit of waiting id: %v", err)
154		}
155		bad := envFE
156		bad.Message.Payload = "changed"
157		if _, err := q.Submit(bad); !errors.Is(err, ErrConflict) {
158			t.Fatalf("different content under same raw id must conflict: %v", err)
159		}
160		if _, err := q.Submit(envFF); !errors.Is(err, ErrTerminal) {
161			t.Fatalf("terminal raw-bytes id resubmit must return ErrTerminal: %v", err)
162		}
163		if len(q.Queries()) != 4 {
164			t.Fatal("conflict/duplicate resubmits changed record count")
165		}
166	
167		// Full listing keeps the exact bytes and first-submission order.
168		all := q.Queries()
169		for i, want := range []string{idFF, idFE, idFD, "loser"} {
170			if !bytes.Equal([]byte(all[i].ID), []byte(want)) {
171				t.Fatalf("Queries[%d] = % x, want % x", i, all[i].ID, want)
172			}
173		}
174	}
175	
176	// Across close/reopen every raw-bytes id keeps its exact message: the three
177	// look-alike ids stay distinct, the consumed nonce stays attributed to its
178	// raw-bytes winner (a new id on the same triple still replays; the winner
179	// stays success and is never redelivered), and waiting status/attempts/retry
180	// survive with the id. Forcing a compaction in between must change nothing.
181	func TestIDInvalidBytesSurviveReopenAndCompaction(t *testing.T) {
182		idFF := string([]byte{0xFF})
183		idFE := string([]byte{0xFE})
184		idFD := replacementCharID
185	
186		dir := t.TempDir()
187		q, err := Open(dir)
188		if err != nil {
189			t.Fatal(err)
190		}
191		if err := q.RegisterSource("chain-a"); err != nil {
192			t.Fatal(err)
193		}
194		if err := q.UpsertHeader(Header{Chain: "chain-a", Height: 100, Root: "r", Trusted: true}); err != nil {
195			t.Fatal(err)
196		}
197		envFF := idEnvelope(idFF, 50, 100)
198		envFE := idEnvelope(idFE, 60, 101)
199		envFD := idEnvelope(idFD, 70, 100)
200		envLoser := idEnvelope("loser", 50, 100)
201		for _, e := range []Envelope{envFF, envFE, envFD, envLoser} {
202			if _, err := q.Submit(e); err != nil {
203				t.Fatalf("submit % x: %v", e.Message.ID, err)
204			}
205		}
206		if _, err := q.Advance(1000); err != nil {
207			t.Fatal(err)
208		}
209	
210		// A message from an unregistered, exotic-but-valid chain name (NUL bytes
211		// and Chinese are valid UTF-8) terminalizes unknown-source; its reason
212		// embeds the chain name verbatim and must survive the same boundaries.
213		rawChain := "ghost\x00链"
214		alien := Envelope{Message: Message{
215			ID: "alien", From: rawChain, To: "chain-b", Nonce: 1, ProofAt: 1,
216		}}
217		if _, err := q.Submit(alien); err != nil {
218			t.Fatal(err)
219		}
220		if _, err := q.Advance(2000); err != nil {
221			t.Fatal(err)
222		}
223		alienReason := "unknown source chain " + rawChain
224		if got, _ := q.Query("alien"); got.From != rawChain ||
225			!bytes.Equal([]byte(got.Reason), []byte(alienReason)) {
226			t.Fatalf("unknown-source record = from %q reason % x, want %q / % x",
227				got.From, got.Reason, rawChain, alienReason)
228		}
229	
230		if err := q.store.compact(q.snapshot()); err != nil {
231			t.Fatalf("compact: %v", err)
232		}
233		if err := q.Close(); err != nil {
234			t.Fatal(err)
235		}
236	
237		q = reopen(t, dir)
238		defer q.Close()
239	
240		// verifyState asserts the restored records; it is read-only and safe to
241		// run after every reopen.
242		verifyState := func(t *testing.T) {
243			t.Helper()
244			// The three look-alikes resolve to their own distinct messages.
245			for want, env := range map[string]Envelope{idFF: envFF, idFE: envFE, idFD: envFD} {
246				qy, ok := q.Query(want)
247				if !ok {
248					t.Fatalf("id % x vanished after reopen/compaction", want)
249				}
250				if !bytes.Equal([]byte(qy.ID), []byte(want)) || qy.Payload != env.Message.Payload {
251					t.Fatalf("record for % x changed: %+v", want, qy)
252				}
253			}
254			if got, _ := q.Query(idFF); got.Status != StatusSuccess || got.Attempts != 1 {
255				t.Fatalf("winner % x not restored as success: %+v", idFF, got)
256			}
257			if got, _ := q.Query(idFE); got.Status != StatusWaiting || got.Attempts != 2 || got.NextRetry != 4000 {
258				t.Fatalf("waiting % x not restored with schedule: %+v", idFE, got)
259			}
260			if got, _ := q.Query("loser"); got.Status != StatusReplay ||
261				got.Reason != "nonce combination already consumed by message "+idFF {
262				t.Fatalf("replay attribution for loser changed: %+v", got)
263			}
264			if got, _ := q.Query("alien"); got.Status != StatusUnknownSrc || got.Reason != alienReason {
265				t.Fatalf("unknown-source record changed: %+v", got)
266			}
267		}
268	
269		// exerciseResubmits uses the live raw-bytes id and the consumed triple;
270		// it mutates state and runs once per session.
271		exerciseResubmits := func(t *testing.T, againID string) {
272			t.Helper()
273			// Identical resubmit of the live raw-bytes id is idempotent and keeps
274			// whatever schedule the record currently has; a one-byte content change
275			// still conflicts.
276			before, _ := q.Query(idFE)
277			echo, err := q.Submit(envFE)
278			if err != nil || echo.Status != StatusWaiting ||
279				echo.Attempts != before.Attempts || echo.NextRetry != before.NextRetry {
280				t.Fatalf("identical resubmit after reopen changed the record: rec=%+v err=%v", echo, err)
281			}
282			bad := envFE
283			bad.Message.Payload = "changed"
284			if _, err := q.Submit(bad); !errors.Is(err, ErrConflict) {
285				t.Fatalf("content conflict lost after reopen: %v", err)
286			}
287	
288			// New id, same consumed triple: replay, winner stays success and is not
289			// delivered again.
290			if _, err := q.Submit(idEnvelope(againID, 50, 100)); err != nil {
291				t.Fatal(err)
292			}
293			rep, err := q.Advance(3000)
294			if err != nil {
295				t.Fatal(err)
296			}
297			var sawAgain bool
298			for _, r := range rep.Results {
299				if r.ID == idFF {
300					t.Fatalf("successful raw-bytes winner redelivered: %+v", r)
301				}
302				if r.ID == againID {
303					sawAgain = true
304					if r.Status != StatusReplay || r.Reason != "nonce combination already consumed by message "+idFF {
305						t.Fatalf("new id on consumed triple: %+v", r)
306					}
307				}
308			}
309			if !sawAgain {
310				t.Fatalf("new id on the winner's triple was not judged replay: %+v", rep.Results)
311			}
312			if got, _ := q.Query(idFF); got.Status != StatusSuccess {
313				t.Fatalf("winner status changed: %+v", got)
314			}
315			if got, ok := q.Query(againID); !ok || got.Status != StatusReplay ||
316				got.Reason != "nonce combination already consumed by message "+idFF {
317				t.Fatalf("replay record for new id not preserved: ok=%v %+v", ok, got)
318			}
319		}
320	
321		assertOrder := func(t *testing.T, want ...string) {
322			t.Helper()
323			all := q.Queries()
324			if len(all) != len(want) {
325				t.Fatalf("Queries rows = %d, want %d: %+v", len(all), len(want), all)
326			}
327			for i, w := range want {
328				if !bytes.Equal([]byte(all[i].ID), []byte(w)) {
329					t.Fatalf("Queries[%d] = % x, want % x", i, all[i].ID, w)
330				}
331			}
332		}
333	
334		baseOrder := []string{idFF, idFE, idFD, "loser", "alien"}
335		verifyState(t)
336		exerciseResubmits(t, "again-1")
337		assertOrder(t, append(append([]string{}, baseOrder...), "again-1")...)
338		if err := q.Close(); err != nil {
339			t.Fatal(err)
340		}
341	
342		q = reopen(t, dir)
343		verifyState(t)
344		if got, ok := q.Query("again-1"); !ok || got.Status != StatusReplay {
345			t.Fatalf("again-1 replay lost across reopen: ok=%v %+v", ok, got)
346		}
347		assertOrder(t, append(append([]string{}, baseOrder...), "again-1")...)
348		// A further new id on the same triple still replays after the restart.
349		exerciseResubmits(t, "again-2")
350		assertOrder(t, append(append([]string{}, baseOrder...), "again-1", "again-2")...)
351	}
352	
353	// Automatic threshold compaction, triggered by an ordinary Submit, must carry
354	// invalid-UTF-8 ids byte-exactly into the snapshot: an oversized raw-bytes id
355	// supplies the bulk, the small crossing submit pushes past 4 MiB, and both
356	// read identically, in order, after reopen.
357	func TestIDInvalidBytesSurviveAutomaticCompaction(t *testing.T) {
358		const margin int64 = 4096
359	
360		versionFrame := int64(len(encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))))
361		baseSize := int64(len(logMagic)) + versionFrame
362		checkpointFrame := int64(len(encodeFrame(mustMarshal(&logEntry{T: kindAdvance, Now: 1000}))))
363	
364		crossID := "cross" + string([]byte{0xFF})
365		crossEntry := &logEntry{T: kindSubmit, Seq: 1, From: "chain-a", To: "chain-b", Nonce: 2, ProofAt: 1}
366		crossEntry.setID(crossID)
367		crossFrame := int64(len(encodeFrame(mustMarshal(crossEntry))))
368	
369		// The filler is the seq-0 submit: its seq zero-value is JSON-omitted, so
370		// the framed size measured here is exactly what the real queue writes.
371		fillerFrame := func(idLen int) int64 {
372			e := &logEntry{T: kindSubmit, From: "chain-a", To: "chain-b", Nonce: 1, ProofAt: 1}
373			e.setID(strings.Repeat("\xff", idLen))
374			return int64(len(encodeFrame(mustMarshal(e))))
375		}
376		overhead := fillerFrame(1) - int64(base64.StdEncoding.EncodedLen(1))
377	
378		nCheckpoints := int(margin/checkpointFrame) + 2
379		targetFillerFrame := compactThreshold - margin - baseSize -
380			int64(nCheckpoints)*checkpointFrame - crossFrame
381		if targetFillerFrame <= overhead {
382			t.Fatalf("setup arithmetic leaves no room: target=%d overhead=%d", targetFillerFrame, overhead)
383		}
384		var fillerLen int
385		for lo, hi := 0, int(targetFillerFrame); ; {
386			mid := (lo + hi + 1) / 2
387			if fillerFrame(mid) <= targetFillerFrame {
388				lo = mid
389			} else {
390				hi = mid - 1
391			}
392			if lo == hi {
393				fillerLen = lo
394				break
395			}
396		}
397		if fillerLen == 0 {
398			t.Fatal("filler id length resolved to zero")
399		}
400		fillerID := strings.Repeat("\xff", fillerLen)
401		filler := idEnvelope(fillerID, 1, 1)
402		filler.Message.Payload = ""
403		cross := idEnvelope(crossID, 2, 1)
404		cross.Message.Payload = ""
405	
406		dir := t.TempDir()
407		q, err := Open(dir)
408		if err != nil {
409			t.Fatal(err)
410		}
411		defer q.Close()
412		if q.store.size != baseSize {
413			t.Fatalf("base size mismatch: want %d got %d", baseSize, q.store.size)
414		}
415		// Equal-time checkpoint padding (legal with no messages yet) so the
416		// crossing submit is exactly what trips 4 MiB; snapshots drop the
417		// checkpoints, so the compacted log lands margin below the threshold.
418		for i := 0; i < nCheckpoints; i++ {
419			if _, err := q.Advance(1000); err != nil {
420				t.Fatal(err)
421			}
422		}
423		if q.store.size > compactThreshold {
424			t.Fatalf("padding crossed the threshold early: %d", q.store.size)
425		}
426		if _, err := q.Submit(filler); err != nil {
427			t.Fatalf("filler submit: %v", err)
428		}
429		if q.store.size > compactThreshold {
430			t.Fatalf("filler crossed before the crossing submit: %d", q.store.size)
431		}
432		if _, err := q.Submit(cross); err != nil {
433			t.Fatalf("crossing submit: %v", err)
434		}
435		if q.store.size > compactThreshold {
436			t.Fatalf("auto-compaction did not shrink the log: %d", q.store.size)
437		}
438		if err := q.Close(); err != nil {
439			t.Fatal(err)
440		}
441	
442		q = reopen(t, dir)
443		defer q.Close()
444		got, ok := q.Query(fillerID)
445		if !ok || got.ID != fillerID {
446			t.Fatalf("filler id changed across auto compaction: ok=%v idlen=%d gotlen=%d",
447				ok, len(fillerID), len(got.ID))
448		}
449		if got, ok := q.Query(crossID); !ok || got.ID != crossID {
450			t.Fatalf("crossing id lost across auto compaction: ok=%v % x", ok, got.ID)
451		}
452		all := q.Queries()
453		if len(all) != 2 || all[0].ID != fillerID || all[1].ID != crossID {
454			t.Fatalf("order after auto compaction: %d rows % x / % x", len(all), all[0].ID, all[1].ID)
455		}
456	
457		raw, err := os.ReadFile(filepath.Join(dir, logName))
458		if err != nil {
459			t.Fatal(err)
460		}
461		if !bytes.Contains(raw, []byte(`"idB64":"`)) {
462			t.Fatalf("invalid-UTF-8 ids not stored byte-exactly: %s", raw[:200])
463		}
464		if bytes.Contains(raw, []byte(replacementCharID)) {
465			t.Fatalf("compacted log contains replacement characters for raw-byte ids")
466		}
467	}
468	
469	// Existing state directories keep their meaning: ids an older build saved as
470	// plain JSON are read at face value. A saved U+FFFD is that character, not the
471	// 0xFF an old build may have lost — resubmitting the character idempotently
472	// returns the record, while resubmitting the original invalid bytes conflicts
473	// rather than resurrecting or merging.
474	func TestIDLegacyRecordsReadAtFaceValue(t *testing.T) {
475		dir := t.TempDir()
476		var raw []byte
477		raw = append(raw, logMagic...)
478		raw = append(raw, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
479		raw = append(raw, encodeFrame(mustMarshal(&logEntry{
480			T: kindSubmit, Seq: 0, ID: "txt", From: "a", To: "b", Nonce: 1,
481			Payload: "legacy text", ProofAt: 10,
482		}))...)
483		raw = append(raw, encodeFrame(mustMarshal(&logEntry{
484			T: kindSubmit, Seq: 1, ID: replacementCharID, From: "a", To: "b",
485			Nonce: 2, Payload: "p", ProofAt: 10,
486		}))...)
487		writeRawLog(t, dir, raw)
488	
489		q := reopen(t, dir)
490		defer q.Close()
491		if got, ok := q.Query("txt"); !ok || got.ID != "txt" {
492			t.Fatalf("legacy text id: ok=%v %q", ok, got.ID)
493		}
494		got, ok := q.Query(replacementCharID)
495		if !ok || got.ID != replacementCharID {
496			t.Fatalf("legacy replacement id must be read at face value: ok=%v % x", ok, got.ID)
497		}
498		saved := Envelope{Message: Message{
499			ID: replacementCharID, From: "a", To: "b", Nonce: 2, Payload: "p", ProofAt: 10,
500		}}
501		if _, err := q.Submit(saved); err != nil {
502			t.Fatalf("saved replacement character id must resubmit as itself: %v", err)
503		}
504		// The invalid bytes the old build lost are not guessed back: 0xFF is a
505		// different id from the saved U+FFFD, so it enqueues a distinct record and
506		// neither id finds the other's message.
507		original := saved
508		original.Message.ID = string([]byte{0xFF})
509		if _, err := q.Submit(original); err != nil {
510			t.Fatalf("original invalid bytes are a distinct id, not a conflict with saved U+FFFD: %v", err)
511		}
512		if got, ok := q.Query(replacementCharID); !ok || got.ID != replacementCharID {
513			t.Fatalf("saved U+FFFD record changed: ok=%v % x", ok, got.ID)
514		}
515		if got, ok := q.Query(string([]byte{0xFF})); !ok || got.ID != string([]byte{0xFF}) {
516			t.Fatalf("raw 0xFF id must keep its own new record: ok=%v % x", ok, got.ID)
517		}
518		if len(q.Queries()) != 3 {
519			t.Fatalf("raw 0xFF and saved U+FFFD must not merge: %+v", q.Queries())
520		}
521	}
522	
523	// A checksum-valid record that carries both a plain field and its base64 form,
524	// or an undecodable base64 field, is an inconsistent record no build writes:
525	// opening returns ErrCorrupt and leaves the file byte-for-byte untouched.
526	func TestIDB64InconsistentRecordsRejected(t *testing.T) {
527		submitBoth := &logEntry{
528			T: kindSubmit, Seq: 0, ID: "m", IDB64: "bQ==", From: "a", To: "b",
529			Nonce: 1, Payload: "p", ProofAt: 10,
530		}
531		submitBad := &logEntry{
532			T: kindSubmit, Seq: 0, IDB64: "!!!not-base64!!!", From: "a", To: "b",
533			Nonce: 1, Payload: "p", ProofAt: 10,
534		}
535		successBoth := func() []*logEntry {
536			return []*logEntry{
537				{T: kindSubmit, Seq: 0, ID: "m", From: "a", To: "b", Nonce: 1, Payload: "p", ProofAt: 10},
538				{T: kindResult, Now: 1000, ID: "m", Status: StatusSuccess, Reason: "ok",
539					Attempts: 1, ConsumeFrom: "a", ConsumeTo: "b", ConsumeNonce: 1,
540					ConsumeBy: "m", ConsumeByB64: "bQ=="},
541			}
542		}
543		successBadBy := func() []*logEntry {
544			return []*logEntry{
545				{T: kindSubmit, Seq: 0, ID: "m", From: "a", To: "b", Nonce: 1, Payload: "p", ProofAt: 10},
546				{T: kindResult, Now: 1000, ID: "m", Status: StatusSuccess, Reason: "ok",
547					Attempts: 1, ConsumeFrom: "a", ConsumeTo: "b", ConsumeNonce: 1,
548					ConsumeByB64: "!!!not-base64!!!"},
549			}
550		}
551		waitingBadReason := func() []*logEntry {
552			return []*logEntry{
553				{T: kindSubmit, Seq: 0, ID: "w", From: "a", To: "b", Nonce: 1, Payload: "p", ProofAt: 100},
554				{T: kindResult, Now: 1000, ID: "w", Status: StatusWaiting, ReasonB64: "!!!not-base64!!!",
555					Attempts: 1, NextRetry: 2000},
556			}
557		}
558	
559		cases := map[string][]*logEntry{
560			"submit with both id and idB64":         {submitBoth},
561			"submit with undecodable idB64":         {submitBad},
562			"success with both consumeBy forms":     successBoth(),
563			"success with undecodable consumeByB64": successBadBy(),
564			"waiting with undecodable reasonB64":    waitingBadReason(),
565		}
566		for name, entries := range cases {
567			t.Run(name, func(t *testing.T) {
568				dir := t.TempDir()
569				var data []byte
570				data = append(data, logMagic...)
571				data = append(data, encodeFrame(mustMarshal(&logEntry{T: kindVersion, V: currentLogV}))...)
572				for _, e := range entries {
573					data = append(data, encodeFrame(mustMarshal(e))...)
574				}
575				writeRawLog(t, dir, data)
576				assertCorruptAndUntouched(t, dir, data)
577			})
578		}
579	}
580	
581	// The empty id stays rejected by the Go API as an invalid argument.
582	func TestIDEmptyStillRejected(t *testing.T) {
583		q, _ := openTempQueue(t)
584		defer q.Close()
585		_, err := q.Submit(Envelope{Message: Message{ID: "", From: "a", To: "b", Nonce: 1, ProofAt: 1}})
586		if !errors.Is(err, ErrInvalidArg) {
587			t.Fatalf("empty id: want ErrInvalidArg, got %v", err)
588		}
589	}
