			t.Fatal(err)
		}
		// plain success then a loser that replays naming a raw-bytes winner
		if _, err := q.Submit(Envelope{Message: Message{
			ID: "plainwin", From: "chain-a", To: "t\xffo", Nonce: 50,
			Payload: "plain", ProofAt: 100,
		}}); err != nil {
			t.Fatal(err)
		}
		// unknown-source: reason embeds raw chain name
		if _, err := q.Submit(Envelope{Message: Message{
			ID: "alien", From: "ghost\x00链", To: "chain-b", Nonce: 1,
