	submitByID := func(entries [][]byte) map[string][]byte {
		m := map[string][]byte{}
		for _, body := range entries {
			var e logEntry
			if err := json.Unmarshal(body, &e); err != nil {
				t.Fatal(err)
			}
			if e.T == kindSubmit {
				m[decodedID(t, body)] = body
			}
		}
		return m
	}
	lastStatusByID := func(entries [][]byte, wantKind string) map[string][]byte {
		m := map[string][]byte{}
		for _, body := range entries {
			var e logEntry
			if err := json.Unmarshal(body, &e); err != nil {
				t.Fatal(err)
			}
